code_sketch:
struct visitor;
struct circle;
struct rect;
struct acceptor { void (*accept)(struct acceptor *, struct visitor *); };

struct visitor {
    const char *name;
    void (*visit_circle)(struct visitor *, struct circle *);
    void (*visit_rect)(struct visitor *, struct rect *);
};
struct circle { struct acceptor base; double r; };

static void circle_accept(struct acceptor *self, struct visitor *v)
{
    if (v && v->visit_circle)           /* NULL slot == cannot visit Circle */
        v->visit_circle(v, (struct circle *)self);
    else if (v)
        log_unhandled("circle", v->name);
}
